 set('foundation',`<div class="v-foundation"><div class="v-course-panel">${ring}<div><span class="v-legend teal">한글 <b>32</b></span><span class="v-legend coral">영어 <b>39</b></span><p>소리·글자·낱말을<br>단계별로 연결하는 커리큘럼</p></div></div><div class="v-content-panel">${label('STORY LIBRARY')}<div class="v-covers">${['series-changjak-mina-01.webp','series-changjak-pongi-01.webp','series-changjak-coco-01.webp','giant-cover-en.webp'].map(f=>img(f,'실제 동화책 표지')).join('')}</div><div class="v-content-labels"><span>명작·전래</span><span>생활·자연관찰</span><span>창작 시리즈</span></div></div></div>${sequence([['book','이야기·파닉스','그림·소리·문맥'],['blocks','낱말과 활동','블록·쓰기·디지털 놀이'],['chart','부모의 기록','수집된 활동 근거']])}<details class="v-evidence"><summary>집계 기준과 실제 제품 범위</summary>${foundation}</details>`);
 const previousProduction=old('production');
 set('production',sequence([['book','기획·교육 설계','소재·언어·학습 목적'],['screen','AI 제작 보조','글·그림·음성'],['check','사람의 편집·검수','캐릭터·문장·발음'],['blocks','제품·활동 연결','블록·쓰기·새 언어']])+`<div class="v-proof"><div>${label('ACTUAL PRODUCTION RECORD')}<strong>50<small>권</small> <span>／</span> 500<small>장</small></strong><p>미나 시리즈 · 2026년9월 삽화 제작·검수·등록 기록</p><p>캐릭터와 제작 구조를 재사용하고, 완성본의 품질은 사람이 확인합니다.</p></div>${img('series-changjak-mina-01.webp','실제 미나 시리즈 표지')}</div><details class="v-evidence"><summary>제작 근거·비용 측정과 모델 조건</summary>${previousProduction}</details>`);
 const previousAdvantage=old('advantage');
