 const previousMarket=old('market');set('market',`<div class="v-map-route">${node('hand','01 한국에서 시작','한글·영어 콘텐츠와 블록·쓰기 제품','v-route-first')}<span class="v-arrow">→</span>${node('globe','02 아시아 첫 시장','현지 언어·가격·사용 환경 검증')}<span class="v-arrow">→</span>${node('check','03 다음 국가로','현지 사용·판매·지원 모델 재현')}</div><div class="v-takeaway">이야기는 언어를 넓히고,<b>제품과 학습 설계는 각 나라에 맞춥니다.</b></div><details class="v-evidence"><summary>국가 선택·현지화·시장 산정 조건</summary>${previousMarket}</details>`);
 const previousGrowth=old('growth');set('growth',`<div class="v-growth"><div>${label('DISCOVERY')}${icon('screen')}<h3>검색 · 영상 · 공유</h3><p>네이버·Google·YouTube·Instagram</p></div><div>${label('EXPERIENCE')}${icon('book')}<h3>같은 이야기 체험</h3><p>한글 ㅂ · 영어 cat · 거인의 정원</p></div><div>${label('PRODUCT')}${icon('blocks')}<h3>블록 · 쓰기 제품 이해</h3><p>직접 해보는 장면 · 사용 가치</p></div><div>${label('RETURN')}${icon('check')}<h3>구매 · 반복 사용</h3><p>새 콘텐츠와 다음 놀이</p></div></div>${caption('유입·구매·반복 사용의 설계도이며 측정된 전환율을 나타내지 않습니다.')}<details class="v-evidence"><summary>채널별 역할과 비용 확인</summary>${previousGrowth}</details>`);
 const previousBusiness=old('business');set('business',`<div class="v-sales-duo"><article>${label('PRODUCT 01')}${photo('activity-kr-block.svg','실물 블록 놀이 활동 도해','제품 활동 도해')}<h3>탱고 한글·영어 블록</h3><p>직접 조합하고 만드는 언어 놀이</p><span class="v-tag">하드웨어 판매</span></article><article>${label('PRODUCT 02')}${photo('duck-note-link.svg','탱고 노트 쓰기 연계 도해','제품 연계 기획 도해')}<h3>탱고 노트</h3><p>읽은 글자와 낱말을 손으로 쓰기</p><span class="v-tag">하드웨어 판매</span></article></div><div class="v-service-strip">${icon('book')}<b>디지털 콘텐츠</b><span>구매 전 체험 → 구매 후 새로운 놀이와 지속 사용</span></div><details class="v-evidence"><summary>제품별 판매 구성·혜택·미확정 조건</summary>${previousBusiness}</details>`);
